#!/usr/bin/env bash
set -u
echo "== 解包图谱视觉升级 =="
mkdir -p /tmp/xm-viz && rm -rf /tmp/xm-viz/site && mkdir -p /tmp/xm-viz/site
echo '' | base64 -d > /tmp/xm-viz/u.tgz
tar -xzf /tmp/xm-viz/u.tgz -C /tmp/xm-viz/site
echo "== 覆盖到站点 =="
sudo cp -r /tmp/xm-viz/site/. /var/www/xinmo-site/
echo "== 校验 =="
grep -c 'IcosahedronGeometry' /var/www/xinmo-site/assets/js/memory-graph.js
grep -c 'mg-spin\|FogExp2' /var/www/xinmo-site/assets/css/memory-graph.css
echo "== DONE =="
